63	func (s *Store) ListUserSettings(ctx context.Context, find *FindUserSetting) ([]*storepb.UserSetting, error) {
64		userSettingRawList, err := s.driver.ListUserSettings(ctx, find)
65		if err != nil {
66			return nil, err
67		}
68	
69		userSettings := []*storepb.UserSetting{}
70		for _, userSettingRaw := range userSettingRawList {
71			userSetting, err := convertUserSettingFromRaw(userSettingRaw)
72			if err != nil {
73				return nil, err
74			}
75			if userSetting == nil {
76				continue
77			}
78			s.userSettingCache.Set(ctx, getUserSettingCacheKey(userSetting.UserId, userSetting.Key.String()), userSetting)
